import{_ as i,a0 as s,w as a,s as u,ao as l,I as n,x as e,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"保持對雲服務供應商選擇的多樣性 | LCTT x X-CMD","titleTemplate":false,"description":"保持對雲服務供應商選擇的多樣性 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保持對雲服務供應商選擇的多樣性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保持對雲服務供應商選擇的多樣性 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20220509 Cloud service providers- How to keep your options open","title":"保持對雲服務供應商選擇的多樣性","tag":"202312","desc":""},"relativePath":"202312/20220509 Cloud service providers- How to keep your options open.md","filePath":"[post].md"}'),d={name:"202312/20220509 Cloud service providers- How to keep your options open.md"};function f(m,t,T,k,S,x){const o=s("Link");return a(),u("div",null,[t[26]||(t[26]=l('<h1 id="保持對雲服務供應商選擇的多樣性" tabindex="-1">保持對雲服務供應商選擇的多樣性 <a class="header-anchor" href="#保持對雲服務供應商選擇的多樣性" aria-label="Permalink to “保持對雲服務供應商選擇的多樣性”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202312/17/223915neao8gei208poo8c.jpg" alt=""></p><blockquote><p>不論雲服務的開放程度如何，你都能為自己的環境選擇合適的方式。</p></blockquote><p>對於 Linux 用户來説，市場上有一種新型的電腦出現，我們稱之為“雲”。</p><p>如同你桌面上的個人電腦，背包裏的筆記本電腦，或是你租用的虛擬私有服務器一樣，你可以選擇不同的雲計算供應商。雖然品牌名稱和你以往熟悉的硬件品牌不一致，但其核心概念是相同的。</p><p>要運行 Linux，你需要一台電腦。要在雲上運行 Linux，你需要一個雲服務供應商。就像你的電腦中的硬件和固件一樣，你的計算堆棧可以使用多大的開源程度也是有區別的。</p><p>作為一個開源的用户，我更偏向於擁有儘量開放的計算集成環境。在對雲計算市場進行詳細的調研後，我形成了關於雲服務供應商的三層觀點。你可以根據這個體系作為指南，對你將選擇的雲供應商作出明確的決策。</p><h3 id="開放堆棧" tabindex="-1">開放堆棧 <a class="header-anchor" href="#開放堆棧" aria-label="Permalink to “開放堆棧”">​</a></h3><p>一個完全開放的雲是從底層開始就建立在開源技術之上的雲。由於雲科技中有很大一部分從一開始就是開源的，因此技術層面的開放性堆棧並不難以實現。然而，也有云供應商以專有的方式重新發明輪子，這讓用户很容易誤入使用了許多封閉源碼組件的雲服務商的陷阱中。</p>',9)),n("p",null,[t[1]||(t[1]=e("如果你在尋找一個真正開放的雲，那麼你應該尋找一個提供 ",-1)),p(o,{href:"https://opensource.com/resources/what-is-openstack"},{default:r(()=>[...t[0]||(t[0]=[e("OpenStack",-1)])]),_:1}),t[2]||(t[2]=e(" 作為基礎的雲供應商。OpenStack 提供雲的軟件基礎設施，包括通過 Neutron 實現的軟件定義網絡（SDN）、通過 Swift 實現的對象存儲、身份和密鑰管理、鏡像服務等等。按照我的硬件電腦比喻，OpenStack 就是驅動雲的“內核”。",-1))]),t[27]||(t[27]=n("p",null,"當然，我並不是字面上的意思，但如果你的雲供應商運行 OpenStack，那相當於你可以直接到達堆棧的底部。從用户的角度看，OpenStack 是你的雲存在並擁有文件系統、網絡等的原因所在。",-1)),n("p",null,[t[4]||(t[4]=e("在 OpenStack 的主體上，可能有一個像 Horizon 或 Skyline 這樣的網絡用户界面，可能有像 ",-1)),p(o,{href:"https://cloud.redhat.com/?intcmp=7013a000002qLH8AAM"},{default:r(()=>[...t[3]||(t[3]=[e("OpenShift",-1)])]),_:1}),t[5]||(t[5]=e(" 或 OKD（並不是一個縮寫，但前身是 OpenShift Origin）這樣的額外組件。所有這些都是開源的，它們幫助你運行容器，這些容器是內嵌應用程序的極簡 Linux 鏡像。",-1))]),t[28]||(t[28]=l('<p>因為 OpenShift 和 OKD 不需要 OpenStack，這就構成了我對雲世界的下一個視野級別。</p><h3 id="開放平台" tabindex="-1">開放平台 <a class="header-anchor" href="#開放平台" aria-label="Permalink to “開放平台”">​</a></h3><p>你並不總是可以選擇你的雲正在運行的堆棧。你的雲可能運行的是 Azure、AWS，或者類似的東西，而不是 OpenStack。</p><p>這些就是雲世界的“二進制碎片”。你對它們如何工作，或者為什麼工作一無所知；你只知道你的雲存在，並且有一個文件系統，一個網絡堆棧，等等。</p><p>就像桌面計算一樣，你可以在獲得的服務器上運行一個“操作系統”。言下之意，有一種觀點認為 OpenStack 本質上就是雲計算的操作系統。然而，通常情況下，用户直接交互的是 OpenShift。</p><p>OpenShift 是一個你可以使用 Podman 和 Kubernetes 管理容器和 <ruby>容器莢<rt>Pod</rt></ruby> 的開源“桌面”或工作區。它讓你在雲上運行應用程序，就像你在筆記本電腦上啓動一個應用一樣。</p><h3 id="開放標準" tabindex="-1">開放標準 <a class="header-anchor" href="#開放標準" aria-label="Permalink to “開放標準”">​</a></h3><p>最後，同樣重要的一點是，有些情況下你在選擇雲服務供應商上沒有什麼選擇。你被放在一個運行着專有“內核”、專有“操作系統”的平台上，你能影響的只剩下你在那個環境裏運行什麼。</p><p>但掌握開源的力量，你就能建立你自己的平台。你可以選擇在容器內部使用的組件。你可以，而且應該，圍繞開源工具設計你的工作環境，因為這樣一來，如果你有機會更換服務供應商，你可以將你的所有工作遷移到新的供應商那裏。</p><p>這可能需要你自行實現一些在你當前受限（非開源）平台上已經內置的功能。例如，你的雲供應商可能會用一個包含在他們平台“免費”提供的 API 管理系統或持續集成/持續交付（CI/CD）管道來吸引你，這需要你有清醒的認識。當一個非開放的應用被免費提供時，通常會以其他形式帶來一些成本。其中一種成本是，一旦你開始在它的基礎上構建，你會更加不願意遷移，因為你會離開你已建立的一切。</p>',10)),n("p",null,[t[8]||(t[8]=e("你應當為自己重建這些封閉“特性”，並將其轉化為開源服務。在容器中運行 ",-1)),p(o,{href:"https://opensource.com/article/19/9/intro-building-cicd-pipelines-jenkins"},{default:r(()=>[...t[6]||(t[6]=[e("Jenkins",-1)])]),_:1}),t[9]||(t[9]=e(" 和 ",-1)),p(o,{href:"https://www.apiman.io/latest/"},{default:r(()=>[...t[7]||(t[7]=[e("APIMan",-1)])]),_:1}),t[10]||(t[10]=e("。找出你的雲提供商聲稱用專有代碼解決的問題，然後使用開源解決方案來確保，當你離開尋找開放的供應商時，你可以遷移你已經構建的系統。",-1))]),t[29]||(t[29]=n("h3",{id:"開源計算",tabindex:"-1"},[e("開源計算 "),n("a",{class:"header-anchor",href:"#開源計算","aria-label":"Permalink to “開源計算”"},"​")],-1)),t[30]||(t[30]=n("p",null,"對於太多的人來説，雲計算是一個開源居於次要地位的領域。實際上，開源在雲上的重要性與它在你的個人電腦和驅動互聯網的服務器上同樣重要。",-1)),t[31]||(t[31]=n("p",null,"尋找開源的雲服務。",-1)),t[32]||(t[32]=n("p",null,"當你受困於無法獲取源代碼的環境時，就肩負起在你的雲內使用開源軟件的責任吧。",-1)),t[33]||(t[33]=n("p",null,[n("em",null,"（題圖：DA/9dc5a9d0-d664-492f-890a-b437ce39c4d6）")],-1)),t[34]||(t[34]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=e("via: ",-1)),p(o,{href:"https://opensource.com/article/22/5/cloud-service-providers-open"},{default:r(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/22/5/cloud-service-providers-open",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("作者：",-1)),p(o,{href:"https://opensource.com/users/seth"},{default:r(()=>[...t[13]||(t[13]=[e("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),p(o,{href:"https://github.com/lkxed"},{default:r(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),p(o,{href:"https://linux.cn/lctt/ChatGPT"},{default:r(()=>[...t[15]||(t[15]=[e("ChatGPT",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),p(o,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const P=i(d,[["render",f]]);export{O as __pageData,P as default};
